//autogenerated:yes
//nolint:revive,govet,errcheck
package ardupilotmega_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/ardupilotmega"
)

func TestEnum_MAV_REMOTE_LOG_DATA_BLOCK_STATUSES(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_REMOTE_LOG_DATA_BLOCK_STATUSES
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MAV_REMOTE_LOG_DATA_BLOCK_NACK.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_REMOTE_LOG_DATA_BLOCK_STATUSES
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MAV_REMOTE_LOG_DATA_BLOCK_NACK, dec)
	})
}
